import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, Navigate } from 'react-router-dom';
import Home from './Home';
import AdminLogin from './AdminLogin';
import AdminPanel from './AdminPanel';
import UserPanel from './UserPanel';

function App(){
  const [adminToken, setAdminToken] = useState('');
  const [userToken, setUserToken] = useState('');

  return (
    <Router>
      <div style={{padding:20,fontFamily:'sans-serif'}}>
        <h1>Traffic Challan System (Demo)</h1>
        <nav style={{marginBottom:20}}>
          <Link to="/">Home</Link> |{" "}
          <Link to="/admin/login">Admin Login</Link> |{" "}
          <Link to="/admin">Admin Panel</Link> |{" "}
          <Link to="/user">User Panel</Link>
        </nav>

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/admin/login" element={
            <AdminLogin onLoginSuccess={(token)=>{ setAdminToken(token); }} />
          } />
          <Route path="/admin" element={
            adminToken ? <AdminPanel adminToken={adminToken} /> : <Navigate to="/admin/login" />
          } />
          <Route path="/user" element={<UserPanel setUserToken={setUserToken} userToken={userToken} />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
